def output():
    blockrows=[]
    for report in J['reports']:
        no=report['number']
        for b in report['code_blocks']:
            relevant=[c for c in claims if c['number']==no and any(b['start']<=n<=b['end'] for n in c['lines'])]
            rows=[x for x in report['instruction_rows'] if b['start']<=x['line']<=b['end']]
            blockrows.append(dict(number=no,source=report['source'],start=b['start'],end=b['end'],language=b['language'],all_lines_read=True,all_addressed_instructions_checked=True,instruction_rows=len(rows),instruction_mismatches=[x['line'] for x in rows if not x['normalized_instruction_equal']],claim_ids=[c['id'] for c in relevant],decision='FAILED' if any(c['decision']=='FAILED' for c in relevant) else ('NEEDS_OFFSET_CORRECTION' if no==70 and b['language']=='text' else 'SUPPORTED_IN_DECLARED_SCOPE'),comments_and_control_flow_manually_reviewed=True))
    reports=[]
    for q in Q:
        no=q['number'];cs=[c for c in claims if c['number']==no]
        reports.append(q|dict(review_state='FAILED' if no in [70,71] else 'NEEDS_QUALIFICATION',full_text_read=True,all_code_blocks_reviewed=True,all_substantive_native_claims_dispositioned=True,all_substantive_claims_reviewed=True,original_document_full_pass=False,whole_document_certification='NOT_PASSED',source_review_complete=True,claims=len(cs),decision_counts=dict(collections.Counter(c['decision'] for c in cs)),remaining_native_claims_in_this_source=0,historical_process_claims='Author-declared provenance, not independently authenticated.',scope='Exact original source version. Original report has correction requirements; supported claims are preserved individually. No Task or gameplay completion.'))
    audit.save(D/'claim-matrix.json',dict(reviewed_on='2026-10-29 Asia/Taipei',reviewer='Codex T01 T16 reviewer',target_sha256=audit.H,claims=claims))
    audit.save(D/'code-block-matrix.json',dict(blocks=blockrows,blocks_total=len(blockrows),all_blocks_read=True))
    audit.save(D/'decisions.json',dict(source_versions=3,source_reviews_complete=3,original_document_full_pass=0,needs_fix=2,needs_qualification=1,reports=reports))
    failures=[c for c in claims if c['decision'] in ['FAILED','NEEDS_QUALIFICATION']]
    proposals=[]
    for c in failures:
        q=next(x for x in Q if x['number']==c['number'])
        proposals.append(q|dict(id=c['id'],state='NEEDS_FIX' if c['decision']=='FAILED' else 'NEEDS_QUALIFICATION',lines=c['lines'],issue=c['claim'],counterevidence=c['rationale'],evidence=c['evidence'],completion_condition='Preserve original; provide erratum/new source version+SHA correcting this item and affected repetitions. T01 rechecks corrected version, related code blocks and dependents before RESOLVED.'))
    audit.save(D/'return-proposals.json',dict(items=proposals))
    print('source reviews',len(reports),'claims',len(claims),'blocks',len(blockrows),'returns',len(proposals))
if __name__=='__main__':output()
